CREATE TABLE ipas_attempts (ordinal INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, question_id TEXT NOT NULL REFERENCES ipas_questions(id), owner_id TEXT NOT NULL, choice TEXT NOT NULL CHECK(choice IN ('A','B','C','D')), correct INTEGER NOT NULL CHECK(correct IN (0,1)), created_at TEXT NOT NULL, FOREIGN KEY(session_id,owner_id) REFERENCES ipas_sessions(id,owner_id), UNIQUE(session_id,question_id));
